/// <summary>
/// One build of the handheld item snapshot (Mobile item snapshot): the item list as ZIP files a
/// device downloads on a full re-sync instead of paging through getSkuPage (load test, 13 Nov: 86
/// minutes for 1M items). Its files are HSMobileOpsSkuSnapshotFile rows with the file attached.
/// Only the newest Ready build is offered; a new one replaces it once all its files are written.
/// </summary>
public class HSMobileOpsSkuSnapshot extends common
{
}

Method.Source:
/// <summary>
/// The snapshot devices get: the newest Ready build of the current company.
/// </summary>
public static HSMobileOpsSkuSnapshot current()
{
    HSMobileOpsSkuSnapshot snapshot;

    select firstOnly snapshot
        order by snapshot.BuiltAtUtc desc
        where snapshot.Status == HSMobileOpsSkuSnapshot::statusReady();
    return snapshot;
}
